import { mkdir, readFile, writeFile } from 'node:fs/promises';

const root = new URL('../', import.meta.url);
const source = new URL('node_modules/@vercel/speed-insights/', root);
const target = new URL('core/static/core/js/vendor/', root);
await mkdir(target, { recursive: true });
const code = await readFile(new URL('dist/index.mjs', source), 'utf8');
await writeFile(new URL('vercel-speed-insights.mjs', target),
  '// Generated by npm run build:frontend. License: vercel-speed-insights.LICENSE.txt\n' +
  code.replace(/^\/\/# sourceMappingURL=.*$/gm, ''));
await writeFile(new URL('vercel-speed-insights.LICENSE.txt', target),
  await readFile(new URL('LICENSE', source), 'utf8'));
console.log('Speed Insights preparado para os arquivos estáticos do Django.');
